# PTX source for RMS Normalization (FP16 input/output) on SM80
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel(
    .param .u64 x_ptr,
    .param .u64 y_ptr,
    .param .u32 batch,
    .param .u32 features,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .f32 eps
)
{
    // -----------------------------------------------------------------
    // Load parameters
    // -----------------------------------------------------------------
    .reg .u64 %x_ptr, %y_ptr;
    .reg .u32 %batch, %features, %dim1, %dim2;
    .reg .f32 %eps;

    ld.param.u64 %x_ptr, [x_ptr];
    ld.param.u64 %y_ptr, [y_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %features, [features];
    ld.param.u32 %dim1, [dim1];
    ld.param.u32 %dim2, [dim2];
    ld.param.f32 %eps, [eps];

    // -----------------------------------------------------------------
    // Thread / block indices
    // -----------------------------------------------------------------
    .reg .u32 %tid, %bid;
    mov.u32 %tid, %tid.x;
    mov.u32 %bid, %ctaid.x;

    // -----------------------------------------------------------------
    // Compute (batch, d1, d2) from linear block id
    // -----------------------------------------------------------------
    .reg .u32 %dim1dim2, %b, %rem, %d1, %d2, %temp;
    mul.lo.u32 %dim1dim2, %dim1, %dim2;          // dim1 * dim2
    div.u32   %b, %bid, %dim1dim2;              // batch index
    mul.lo.u32 %temp, %b, %dim1dim2;
    sub.u32   %rem, %bid, %temp;                // rem = bid % (dim1*dim2)
    div.u32   %d1, %rem, %dim2;                 // d1
    mul.lo.u32 %temp, %d1, %dim2;
    sub.u32   %d2, %rem, %temp;                 // d2

    // -----------------------------------------------------------------
    // Compute linear index of element (b, tid, d1, d2)
    // idx = ((b * features + tid) * dim1 + d1) * dim2 + d2
    // -----------------------------------------------------------------
    .reg .u32 %idx32;
    mul.lo.u32 %idx32, %b, %features;    // b * features
    add.u32    %idx32, %idx32, %tid;      // + tid
    mul.lo.u32 %idx32, %idx32, %dim1;     // * dim1
    add.u32    %idx32, %idx32, %d1;       // + d1
    mul.lo.u32 %idx32, %idx32, %dim2;     // * dim2
    add.u32    %idx32, %idx32, %d2;       // + d2

    .reg .u64 %offset, %addr_in, %addr_out;
    cvt.u64.u32 %offset, %idx32;
    mul.lo.u64 %offset, %offset, 2;        // sizeof(__half) == 2
    add.u64 %addr_in, %x_ptr, %offset;
    add.u64 %addr_out, %y_ptr, %offset;

    // -----------------------------------------------------------------
    // Load input element (FP16) and convert to FP32
    // -----------------------------------------------------------------
    .reg .f16 %x_half;
    .reg .f32 %x_f32, %sq;
    ld.global.nc.f16 %x_half, [%addr_in];
    cvt.f32.f16 %x_f32, %x_half;

    // -----------------------------------------------------------------
    // Square and store to shared memory for reduction
    // -----------------------------------------------------------------
    mul.f32 %sq, %x_f32, %x_f32;

    .shared .align 4 .b32 sdata[64];
    .reg .u32 %shmem_off;
    mul.lo.u32 %shmem_off, %tid, 4;          // offset in bytes
    st.shared.f32 [sdata + %shmem_off], %sq;

    // -----------------------------------------------------------------
    // Reduce sum of squares (single warp reduction via shared memory)
    // -----------------------------------------------------------------
    bar.sync 0;

    .reg .pred %p0, %p1;
    .reg .f32 %sum;
    mov.f32 %sum, 0f0;

    setp.eq.u32 %p0, %tid, 0;
    @%p0 {
        // thread 0 loops over all features
        .reg .u32 %i;
        mov.u32 %i, 0;
    loop_sum:
        mul.lo.u32 %shmem_off, %i, 4;
        .reg .f32 %val;
        ld.shared.f32 %val, [sdata + %shmem_off];
        add.f32 %sum, %sum, %val;
        add.u32 %i, %i, 1;
        setp.lt.u32 %p1, %i, %features;
        @%p1 bra loop_sum;

        // mean = sum / features
        .reg .f32 %mean, %features_f;
        cvt.f32.u32 %features_f, %features;
        div.f32 %mean, %sum, %features_f;

        // add epsilon and sqrt
        add.f32 %mean, %mean, %eps;
        sqrt.approx.f32 %mean, %mean;   // %mean now holds rms

        // store rms to shared memory slot 0 for broadcast
        st.shared.f32 [sdata], %mean;
    }
    bar.sync 0;

    // -----------------------------------------------------------------
    // Load rms, normalize, convert back to FP16 and store
    // -----------------------------------------------------------------
    .reg .f32 %rms;
    ld.shared.f32 %rms, [sdata];

    div.f32 %x_f32, %x_f32, %rms;
    cvt.rn.f16.f32 %x_half, %x_f32;
    st.global.nc.f16 [%addr_out], %x_half;

    ret;
}
'''

# -----------------------------------------------------------------
# Python wrapper that uses the provided PTX harness
# -----------------------------------------------------------------
import torch
from ptx_harness import ptx_load, ptx_launch

class ModelNew:
    def __init__(self, num_features: int, eps: float = 1e-5):
        self.num_features = int(num_features)
        self.eps = float(eps)
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, x: torch.Tensor) -> torch.Tensor:
        if not (x.is_cuda and x.dtype == torch.float16):
            raise ValueError("Input must be a CUDA tensor of dtype torch.float16")
        batch, features, dim1, dim2 = x.shape
        if features != self.num_features:
            raise ValueError(f"Expected feature dimension {self.num_features}, got {features}")
        y = torch.empty_like(x)

        # Grid: one block per (batch, dim1, dim2)
        grid = (batch * dim1 * dim2,)
        # Block: one thread per feature
        block = (features,)

        args = [x, y, batch, features, dim1, dim2, self.eps]
        ptx_launch(self.module, "rmsnorm_kernel", grid, block, args)
        return y
